import { expect, expectStatus, test, type Document, type Extraction } from "../../fixtures";

test("a re-uploaded document is the one that gets reviewed", { tag: "@LIF-01" }, async ({ factory, apiAs }) => {
  // Arrange: a draft vendor with insurance certificate and contract extracted.
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate.txt", "member");
  await factory.upload(vendor.id, "contract", "contract.txt", "member");

  const w9Text = (legalName: string) =>
    `Legal Name: ${legalName}\nTax ID: 84-2219067\nBusiness Type: LLC\n`;
  const uploadW9 = async (legalName: string, file: string) =>
    expectStatus<Document>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: { name: file, mimeType: "text/plain", buffer: Buffer.from(w9Text(legalName)) },
        },
      }),
      201,
    );

  // First W-9, then wait for it to be extracted before replacing it.
  const firstW9 = await uploadW9("First Name LLC", "w9-first.txt");
  await expect
    .poll(async () => {
      const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
      return docs.filter((d) => d.id === firstW9.id).map((d) => d.status);
    }, { timeout: 30_000 })
    .toEqual(["extracted"]);

  // Second W-9 uploaded; wait for all four documents to be extracted.
  const secondW9 = await uploadW9("Second Name LLC", "w9-second.txt");
  await expect
    .poll(async () => {
      const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
      return docs.length === 4 && docs.every((d) => d.status === "extracted");
    }, { message: "all four documents extracted", timeout: 30_000 })
    .toBe(true);

  // Act: submit the vendor, then the reviewer reads the queue.
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const reviewer = await apiAs("reviewer");
  const queue = await expectStatus<
    { vendor_id: string; extractions: Extraction[] & { kind: string; fields: Record<string, { value: string | null }> }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);

  // Assert: the queue's W-9 extraction carries the second upload's legal name.
  const item = queue.find((q) => q.vendor_id === vendor.id);
  expect(item, "vendor appears in the review queue").toBeDefined();
  const w9Extractions = (item!.extractions as unknown as { kind: string; fields: Record<string, { value: string | null }> }[]).filter(
    (e) => e.kind === "w9",
  );
  expect(w9Extractions).toHaveLength(1);
  expect(w9Extractions[0].fields.legal_name.value).toBe("Second Name LLC");

  // Assert: the documents list has both W-9 uploads, oldest first.
  const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
  const w9s = docs.filter((d) => d.kind === "w9");
  expect(w9s.map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);
  expect(Date.parse((w9s[0] as unknown as { created_at: string }).created_at)).toBeLessThanOrEqual(
    Date.parse((w9s[1] as unknown as { created_at: string }).created_at),
  );
});
